import 'package:flutter/material.dart';import 'package:cloud_firestore/cloud_firestore.dart';import '../../../services/auth/auth_service.dart';import '../../../services/social/random_connect_service.dart';
class AurenRandomConnectScreen extends StatefulWidget{const AurenRandomConnectScreen({super.key});@override State<AurenRandomConnectScreen> createState()=>_AurenRandomConnectScreenState();}
class _AurenRandomConnectScreenState extends State<AurenRandomConnectScreen>{final auth=FirebaseAurenAuthService();final s=AurenRandomConnectService();final name=TextEditingController(),lang=TextEditingController(),interest=TextEditingController(),goal=TextEditingController();String? requestId;@override void dispose(){for(final c in [name,lang,interest,goal])c.dispose();super.dispose();}Future<void> join()async{final uid=auth.currentUserId;if(uid==null||lang.text.trim().isEmpty)return;requestId=await s.join(uid:uid,displayName:name.text,language:lang.text,interest:interest.text,goal:goal.text);if(mounted)setState((){});}Future<void> report(String id)async{await FirebaseFirestore.instance.collection('random_connect_reports').add({'requestId':id,'reporterUid':auth.currentUserId,'createdAt':FieldValue.serverTimestamp()});if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('تم إرسال البلاغ للمراجعة.')));}Future<void> cancel()async{final uid=auth.currentUserId;if(uid!=null&&requestId!=null)await s.cancel(uid,requestId!);if(mounted)setState(()=>requestId=null);}@override Widget build(BuildContext context){if(auth.currentUserId==null)return const Scaffold(body:Center(child:Text('سجّل الدخول أولاً.')));return Scaffold(appBar:AppBar(title:const Text('Random Connect')),body:ListView(padding:const EdgeInsets.all(16),children:[const Text('تواصل عشوائياً مع أشخاص حسب اللغة والاهتمام والهدف. البداية نصية؛ الفيديو والصوت يضافان لاحقاً بعد بناء طبقة الأمان والمطابقة.'),const SizedBox(height:16),...[_f(name,'الاسم الظاهر'),_f(lang,'اللغة'),_f(interest,'الاهتمام'),_f(goal,'الهدف')],FilledButton(onPressed:requestId==null?join:cancel,child:Text(requestId==null?'ابحث عن شخص':'إلغاء الانتظار')),if(requestId!=null)const Padding(padding:EdgeInsets.all(20),child:Center(child:CircularProgressIndicator())),const Divider(),StreamBuilder<List<AurenRandomMatch>>(stream:s.watchWaiting(language:lang.text,interest:interest.text),builder:(context,snap){final me=auth.currentUserId;final items=(snap.data??const <AurenRandomMatch>[]).where((x)=>x.uid!=me).toList();return Column(children:items.map((x)=>Card(child:ListTile(leading:const CircleAvatar(child:Icon(Icons.person_outline)),title:Text(x.displayName),subtitle:Text([x.language,x.interest,x.goal].where((v)=>v.isNotEmpty).join(' • ')),trailing:Wrap(spacing:4,children:[FilledButton(onPressed:()=>s.connect(me!,x.id),child:const Text('Connect')),IconButton(tooltip:'Report',onPressed:()=>report(x.id),icon:const Icon(Icons.flag_outlined))]))).toList());})]));}Widget _f(TextEditingController c,String l)=>Padding(padding:const EdgeInsets.only(bottom:10),child:TextField(controller:c,decoration:InputDecoration(labelText:l,border:const OutlineInputBorder())));}